//! The Ancient Greek model, generated by flexion-train from configs/src/ancient_greek.rs: one
//! module per part of speech (and per helper model), each a
//! [`flexion::PosModel`]. Don't edit by hand.

use flexion::{Model, PosModel, Spelling, SpellingStrings};

mod noun;
mod adjective;
mod verb;
mod pronoun;
mod numeral;
mod noun_restore;
mod noun_restore_front;
mod adjective_restore;
mod adjective_restore_front;
mod verb_restore;
mod verb_restore_front;
mod pronoun_restore;
mod numeral_restore;
mod adjective_from_cell_3;
mod verb_from_cell_135;
mod verb_from_cell_243;
mod verb_from_cell_351;
mod verb_from_cell_360;
mod verb_from_cell_261;

static STRINGS: SpellingStrings<'static> = SpellingStrings {
    stress_marks: "\u{301}\u{342}",
    stress_table: "\u{300}\0aΐϊ0άα0έε0ήη0ίι0ΰϋ0όο0ύυ0ώω0ἂἀaἃἁaἄἀ0ἅἁ0ἆἀ1ἇἁ1ἒἐaἓἑaἔἐ0ἕἑ0ἢἠaἣἡaἤἠ0ἥἡ0ἦἠ1ἧἡ1ἲἰaἳἱaἴἰ0ἵἱ0ἶἰ1ἷἱ1ὂὀaὃὁaὄὀ0ὅὁ0ὒὐaὓὑaὔὐ0ὕὑ0ὖὐ1ὗὑ1ὢὠaὣὡaὤὠ0ὥὡ0ὦὠ1ὧὡ1ὰαaάαaὲεaέεaὴηaήηaὶιaίιaὸοaόοaὺυaύυaὼωaώωaᾂᾀaᾃᾁaᾄᾀ0ᾅᾁ0ᾆᾀ1ᾇᾁ1ᾒᾐaᾓᾑaᾔᾐ0ᾕᾑ0ᾖᾐ1ᾗᾑ1ᾢᾠaᾣᾡaᾤᾠ0ᾥᾡ0ᾦᾠ1ᾧᾡ1ᾲᾳaᾴᾳ0ᾶα1ᾷᾳ1ῂῃaῄῃ0ῆη1ῇῃ1ῒϊaΐϊaῖι1ῗϊ1ῢϋaΰϋaῦυ1ῧϋ1ῲῳaῴῳ0ῶω1ῷῳ1",
    vowels: "αεηιουωϊϋἀἁἐἑἠἡἰἱὀὁὐὑὠὡᾀᾁᾐᾑᾠᾡᾰᾱᾳῃῐῑῠῡῳ",
    implicit: "",
    fold_from: "ς\u{313}\u{314}\u{345}\u{308}ϊϋἀἁἐἑἠἡἰἱὀὁὐὑὠὡᾀᾁᾐᾑᾠᾡᾳῃῳ\u{304}\u{306}ᾰᾱῐῑῠῡ",
    fold_to: "σ\0\0\0\0ιυααεεηηιιοουυωωααηηωωαηω\0\0ααιιυυ",
    strip_marks: "",
    unmark_from: "\u{304}\u{306}ᾰᾱῐῑῠῡ",
    unmark_to: "\0\0ααιιυυ",
    syllabic: "",
    mute: "",
    diphthongs: "αιειοιυιαυευηυουωυ",
    hiatus: "ΐΰϊϋῒΐῗῢΰῧ",
};

/// The model, in the config's order of parts of speech (helper models
/// after).
pub(crate) fn build() -> Model<'static> {
    Model::new(
        Spelling::new(true, true, STRINGS),
        vec![
            &noun::Noun as &dyn PosModel,
            &adjective::Adjective as &dyn PosModel,
            &verb::Verb as &dyn PosModel,
            &pronoun::Pronoun as &dyn PosModel,
            &numeral::Numeral as &dyn PosModel,
            &noun_restore::NounRestore as &dyn PosModel,
            &noun_restore_front::NounRestoreFront as &dyn PosModel,
            &adjective_restore::AdjectiveRestore as &dyn PosModel,
            &adjective_restore_front::AdjectiveRestoreFront as &dyn PosModel,
            &verb_restore::VerbRestore as &dyn PosModel,
            &verb_restore_front::VerbRestoreFront as &dyn PosModel,
            &pronoun_restore::PronounRestore as &dyn PosModel,
            &numeral_restore::NumeralRestore as &dyn PosModel,
            &adjective_from_cell_3::AdjectiveFromCell3 as &dyn PosModel,
            &verb_from_cell_135::VerbFromCell135 as &dyn PosModel,
            &verb_from_cell_243::VerbFromCell243 as &dyn PosModel,
            &verb_from_cell_351::VerbFromCell351 as &dyn PosModel,
            &verb_from_cell_360::VerbFromCell360 as &dyn PosModel,
            &verb_from_cell_261::VerbFromCell261 as &dyn PosModel,
        ],
    )
}

/// Whether every part of speech's sound laws compile.
pub(crate) fn sound_laws_compile() -> bool {
    noun::sound_laws_compile() && adjective::sound_laws_compile() && verb::sound_laws_compile()
}
